import random
from collections import deque

def bfs_dist(adj, s, t, limit):
    # returns shortest distance from s to t, or infinity if > limit
    if s == t: return 0
    dist = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if dist[u] >= limit: continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                if v == t: return dist[v]
                q.append(v)
    return float('inf')

def try_build(n=24, target=35, seed=0):
    random.seed(seed)
    adj = {i: set() for i in range(n)}
    edges = []
    all_pairs = [(u,v) for u in range(n) for v in range(u+1,n)]
    random.shuffle(all_pairs)
    for (u,v) in all_pairs:
        # Check: adding edge creates cycle of length d+1 where d is current dist(u,v)
        # Need cycle length >= 7, so d >= 6
        d = bfs_dist(adj, u, v, 6)
        if d >= 6:  # distance infinity or >=6
            adj[u].add(v); adj[v].add(u)
            edges.append((u,v))
            if len(edges) >= target:
                break
    return edges, adj

best = 0
best_edges = None
for s in range(200):
    edges, adj = try_build(seed=s, target=40)
    if len(edges) > best:
        best = len(edges)
        best_edges = edges
        print(s, best)
    if best >= 35: break

