# Check girth
def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    cyc = dist[u]+dist[v]+1
                    if cyc < g: g = cyc
    return g

