from itertools import product
# Try greedy with DSATUR
def try_color(adj, n, k):
    color = [-1]*n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def bt(i):
        if i == n: return True
        v = order[i]
        used = {color[u] for u in adj[v] if color[u]!=-1}
        for c in range(k):
            if c not in used:
                color[v] = c
                if bt(i+1): return True
                color[v] = -1
        return False
    if bt(0): return color
    return None

